<script>
(function(){
var L={user_preference:"用户偏好",world:"世界设定",plot:"剧情进展",agreement:"约定",general:"其他"};
var d=(window.MEMORY_DATA&&Array.isArray(window.MEMORY_DATA.memories))?window.MEMORY_DATA:{memories:[],updatedAt:null,max:0};
var S={topic:"all",q:""};
function $(i){return document.getElementById(i)}
function lb(t){return L[t]||t||"其他"}
function esc(s){return String(s).replace(/[&<>"']/g,function(c){return {"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]})}
function hl(s,q){
  var safe=esc(s);if(!q)return safe;
  var lq=q.toLowerCase(),ls=safe.toLowerCase(),o="",i=0,j;
  while((j=ls.indexOf(lq,i))>=0){o+=safe.slice(i,j)+"<mark>"+safe.slice(j,j+lq.length)+"</mark>";i=j+lq.length}
  return o+safe.slice(i)
}
function ft(iso){
  if(!iso)return "—";var x=new Date(iso);if(isNaN(x.getTime()))return "—";
  function p(n){return String(n).padStart(2,"0")}
  return x.getFullYear()+"-"+p(x.getMonth()+1)+"-"+p(x.getDate())+" "+p(x.getHours())+":"+p(x.getMinutes())
}
function ago(iso){
  if(!iso)return "";var t=new Date(iso).getTime();if(isNaN(t))return "";
  var s=Math.floor((Date.now()-t)/1000);
  if(s<60)return "刚刚";
  if(s<3600)return Math.floor(s/60)+" 分钟前";
  if(s<86400)return Math.floor(s/3600)+" 小时前";
  return Math.floor(s/86400)+" 天前"
}
function tps(){var seen={},out=[];d.memories.forEach(function(m){var t=m.topic||"general";if(!seen[t]){seen[t]=1;out.push(t)}});return out}
