  var n=d.memories.length,mx=d.max||0;
  $("sTotal").innerHTML=n+'<small id="sMax"> / '+mx+"</small>";
  $("sTopic").textContent=tps().length;
  var pct=mx?Math.min(100,Math.round(n/mx*100)):0,b=$("sBar");
  b.style.width=pct+"%";
  b.style.background=pct>=90?"linear-gradient(90deg,#a8553f,#d9756b)":"linear-gradient(90deg,#a8843f,#e8b465)";
  $("sLast").textContent=n?ago(d.memories[0].used):"—";
  $("stamp").innerHTML="同步时间 "+ft(d.updatedAt)+"<br>"+n+" / "+mx+" 条 · 按触发时间排序"
}
function chips(){
  var box=$("chips"),all=[{k:"all",n:"全部 ("+d.memories.length+")"}];
  tps().forEach(function(t){
    var c=d.memories.filter(function(m){return (m.topic||"general")===t}).length;
    all.push({k:t,n:lb(t)+" ("+c+")"})
  });
