    if(!q)return true;
    return (String(m.content||"")+" "+lb(m.topic)+" "+String(m.id||"")).toLowerCase().indexOf(q)>=0
  });
  var box=$("list");
  if(!items.length){
    box.innerHTML='<div class="empty"><span class="big">✦</span>'+(n?"没有匹配的记忆":"还没有任何记忆<br>对话中一旦有了值得记住的事，它就会出现在这里")+"</div>";
