async function rd(p) { try { const t = await $read(p); return t == null ? '' : String(t); } catch (e) { return null; } }

async function getCfg() {
  const raw = await rd(CONFIG);
  let max = DEFAULT_MAX, autoShow = true;
  if (raw) {
    try {
      const o = JSON.parse(raw);
      const n = Number(o.max);
      if (isFinite(n) && n >= 5 && n <= 1000) max = Math.floor(n);
      if (o.autoShow === false) autoShow = false;
    } catch (e) {}
  }
  return { max, autoShow };
}

function sortByUsed(list) {
  list.sort((a, b) => {
    const ua = a.used || a.time || '', ub = b.used || b.time || '';
    if (ua === ub) return String(a.id).localeCompare(String(b.id));
    return ua < ub ? 1 : -1;
  });
  return list;
}

async function loadAll() {
  const raw = await rd(FILE);
  if (!raw) return [];
  const out = [];
  raw.split('\n').forEach(line => {
    line = line.trim();
    if (!line) return;
    try {
      const o = JSON.parse(line);
      if (o && o.content) {
        if (!o.used) o.used = o.time || nowISO();
        out.push(o);
      }
    } catch (e) {}
  });
  return sortByUsed(out);
}

async function sync(list, max) {
  await $write(DATA, 'window.MEMORY_DATA = ' + JSON.stringify({ updatedAt: nowISO(), count: list.length, max: max, memories: list }) + ';\n');
}

// 排序后从末尾淘汰超限记忆：末尾 = 最久未触发
async function save(list) {
  sortByUsed(list);
  const { max } = await getCfg();
  const evicted = [];
  while (list.length > max) evicted.push(list.pop());
  await $write(FILE, list.map(m => JSON.stringify(m)).join('\n') + (list.length ? '\n' : ''));
  await sync(list, max);
  return evicted;
}

async function ensureBoard(list) {
  const cur = await rd(BOARD);
  let wrote = false;
  if (cur == null || cur.indexOf(MARK) < 0) { await $write(BOARD, BOARD_HTML + '\n'); wrote = true; }
  if (!(await rd(DATA))) { await sync(list || [], (await getCfg()).max); wrote = true; }
  if (!(await rd(CONFIG))) { await $write(CONFIG, JSON.stringify({ max: DEFAULT_MAX, autoShow: true }) + '\n'); wrote = true; }
  return wrote;
}

const fmt = m => '· [' + (m.id || '?') + '] (' + (LABEL[m.topic] || m.topic || '其他') + ') ' + m.content + (m.used ? '  @' + String(m.used).slice(0, 16).replace('T', ' ') : '');
const evt = a => a.length ? '\n因超出上限淘汰最久未触发的 ' + a.length + ' 条：\n' + a.map(fmt).join('\n') : '';

let MEM_OUT;
try {
  const action = String(ARG.action || 'load');
  let list = await loadAll();
  const cfg = await getCfg();
  const max = cfg.max;
  let WROTE = false;

  if (action === 'load') {
    const lim = Math.max(1, Number(ARG.limit) || 100);
    const top = list.slice(0, lim);
    let touched = 0;
    // load 默认只读、不改排序；传 touch=true 才把读到的算作触发
    if (ARG.touch === true) {
      const t = Date.now();
      top.forEach((m, i) => { m.used = new Date(t - i).toISOString(); });
      touched = top.length;
      await save(list);
      WROTE = true;
    }
    MEM_OUT = {
      ok: true, action, count: list.length, max, status: list.length ? 'ok' : 'empty', touched, memories: top,
      text: list.length
        ? '记忆 ' + list.length + '/' + max + ' 条，以下为最近触发的 ' + top.length + ' 条（新→旧，末尾最易被淘汰）：\n' + top.map(fmt).join('\n')
        : '（记忆为空，还没有任何记录）'
    };
  } else if (action === 'store') {
    const content = String(ARG.content || '').trim();
    if (!content) throw new Error('store 需要 content');
    const dup = list.find(m => String(m.content || '').trim() === content);
    if (dup) {
      dup.used = nowISO();
      const ev = await save(list);
      MEM_OUT = { ok: true, action, duplicate: true, id: dup.id, count: list.length, max, evicted: ev, text: '已有相同记忆 [' + dup.id + ']，仅刷新触发时间，未重复写入。' + evt(ev) };
    } else {
      const t = String(ARG.topic || 'general');
      const topic = LABEL[t] ? t : 'general';
      const m = { id: newId(), topic, content, time: nowISO(), used: nowISO() };
      list.unshift(m);
      const ev = await save(list);
      MEM_OUT = {
        ok: true, action, id: m.id, topic, count: list.length, max, evicted: ev,
        text: '已记住 [' + m.id + ']（' + LABEL[topic] + '）：' + content + '\n当前 ' + list.length + '/' + max + ' 条' + evt(ev)
      };
    }
    WROTE = true;
  } else if (action === 'touch') {
    const raw = ARG.ids || ARG.id || ARG.query || '';
    const keys = Array.isArray(raw) ? raw.map(String) : String(raw).split(',').map(s => s.trim()).filter(Boolean);
    if (!keys.length) throw new Error('touch 需要 ids（id，可逗号分隔）或 query');
    const hit = list.filter(m => keys.some(k => m.id === k || String(m.content || '').toLowerCase().includes(k.toLowerCase())));
    if (!hit.length) {
      MEM_OUT = { ok: true, action, touched: [], count: list.length, max, text: '没有找到要触发的记忆，未做改动。' };
    } else {
      const t = Date.now();
      hit.forEach((m, i) => { m.used = new Date(t - i).toISOString(); });
      const ev = await save(list);
      MEM_OUT = { ok: true, action, touched: hit, count: list.length, max, evicted: ev, text: '已把 ' + hit.length + ' 条记忆提到最前面：\n' + hit.map(fmt).join('\n') + evt(ev) };
      WROTE = true;
    }
  } else if (action === 'update') {
    const id = String(ARG.id || '').trim();
    const i = list.findIndex(m => m.id === id);
    if (i < 0) throw new Error('找不到记忆 id：' + id);
    const content = String(ARG.content || '').trim();
    if (content) list[i].content = content;
    if (ARG.topic && LABEL[ARG.topic]) list[i].topic = ARG.topic;
    list[i].updated = nowISO();
    list[i].used = nowISO();
    const ev = await save(list);
    MEM_OUT = { ok: true, action, id, count: list.length, max, memory: list[i], evicted: ev, text: '已更新 [' + id + ']（并提到最前面）：' + list[i].content + evt(ev) };
    WROTE = true;
  } else if (action === 'forget') {
    const key = String(ARG.keyword || ARG.id || '').trim();
    if (!key) throw new Error('forget 需要 keyword（记忆 id 或关键词）');
    const low = key.toLowerCase();
    const del = list.filter(m => m.id === key || String(m.content || '').toLowerCase().includes(low) || m.topic === key || (LABEL[m.topic] || '') === key);
    if (!del.length) {
      MEM_OUT = { ok: true, action, removed: [], count: list.length, max, text: '没有找到匹配「' + key + '」的记忆，未做改动。' };
    } else {
      const ids = new Set(del.map(m => m.id));
      list = list.filter(m => !ids.has(m.id));
      await save(list);
      MEM_OUT = { ok: true, action, removed: del, count: list.length, max, text: '已遗忘 ' + del.length + ' 条记忆：\n' + del.map(fmt).join('\n') };
      WROTE = true;
    }
  } else if (action === 'search') {
    const q = String(ARG.query || '').trim();
    if (!q) throw new Error('search 需要 query');
    const low = q.toLowerCase();
    const lim = Math.max(1, Number(ARG.limit) || 20);
    const hit = list.filter(m => String(m.content || '').toLowerCase().includes(low) || String(m.id || '').toLowerCase().includes(low) || m.topic === q || (LABEL[m.topic] || '').includes(q)).slice(0, lim);
    // 检索命中即视为触发：提到最前，避免常用记忆被淘汰
    if (hit.length && ARG.touch !== false) {
      const t = Date.now();
      hit.forEach((m, i) => { m.used = new Date(t - i).toISOString(); });
      await save(list);
      WROTE = true;
    }
    MEM_OUT = {
      ok: true, action, query: q, count: hit.length, max, memories: hit,
      text: hit.length ? '找到 ' + hit.length + ' 条与「' + q + '」相关的记忆（已提到最前面）：\n' + hit.map(fmt).join('\n') : '没有找到与「' + q + '」相关的记忆。'
    };
  } else if (action === 'list') {
    const byTopic = {};
    list.forEach(m => { const t = m.topic || 'general'; byTopic[t] = (byTopic[t] || 0) + 1; });
    const rows = Object.keys(byTopic).map(t => (LABEL[t] || t) + '：' + byTopic[t] + ' 条');
    MEM_OUT = {
      ok: true, action, count: list.length, max, byTopic, status: list.length ? 'ok' : 'empty',
      text: list.length
        ? '记忆概况：' + list.length + '/' + max + ' 条（' + rows.join('，') + '）\n最近触发：' + String(list[0].used || '').slice(0, 16).replace('T', ' ') + '\n最久未触发（下次写入时最先被淘汰）：\n' + list.slice(-3).reverse().map(fmt).join('\n')
        : '记忆概况：暂无任何记忆（上限 ' + max + ' 条）'
    };
  } else if (action === 'init') {
    const wrote = await ensureBoard(list);
    await $write(CONFIG, JSON.stringify({ max: max, autoShow: cfg.autoShow }) + '\n');
    const ev = await save(list);
    MEM_OUT = { ok: true, action, count: list.length, max, board: BOARD, data: DATA, config: CONFIG, rebuilt: wrote, evicted: ev, text: '已初始化记忆存储与看板：' + BOARD + (wrote ? '（本次重建）' : '（已是最新）') + '，上限 ' + max + ' 条。' };
    WROTE = ev.length > 0;
  } else if (action === 'show') {
    const rebuilt = await ensureBoard(list);
    await save(list);
    if (!(await rd(BOARD))) throw new Error('看板文件 ' + BOARD + ' 无法创建');
    await $display(BOARD, { title: '记忆看板' });
    MEM_OUT = { ok: true, action, count: list.length, max, rebuilt, text: '已打开记忆看板（' + list.length + '/' + max + ' 条）' + (rebuilt ? '，看板文件本次已自动初始化。' : '。') };
  } else {
    throw new Error('未知 action：' + action + '（可用 load / store / touch / update / search / list / forget / init / show）');
  }

  // 记忆有变化时主动打开看板；config.autoShow=false 可关闭
  if (WROTE && MEM_OUT.ok && cfg.autoShow) {
    await ensureBoard(list);
    await $display(BOARD, { title: '记忆看板' });
    MEM_OUT.shown = true;
    MEM_OUT.text += '\n（记忆有更新，已打开看板）';
  }
} catch (e) {
  MEM_OUT = { ok: false, error: String((e && e.message) || e) };
}
result = MEM_OUT;
